ALTER TABLE public.concentradores ADD COLUMN IF NOT EXISTS api_last_success_at timestamptz, ADD COLUMN IF NOT EXISTS api_last_attempt_at timestamptz, ADD COLUMN IF NOT EXISTS api_last_error text, ADD COLUMN IF NOT EXISTS api_interfaces_snapshot jsonb, ADD COLUMN IF NOT EXISTS snmp_last_success_at timestamptz, ADD COLUMN IF NOT EXISTS snmp_last_attempt_at timestamptz, ADD COLUMN IF NOT EXISTS snmp_last_error text, ADD COLUMN IF NOT EXISTS snmp_status text NOT NULL DEFAULT 'unknown';
ALTER TABLE public.rbs ADD COLUMN IF NOT EXISTS organization_id uuid REFERENCES public.organizations(id), ADD COLUMN IF NOT EXISTS snmp_last_success_at timestamptz, ADD COLUMN IF NOT EXISTS snmp_last_attempt_at timestamptz, ADD COLUMN IF NOT EXISTS snmp_last_error text, ADD COLUMN IF NOT EXISTS snmp_status text NOT NULL DEFAULT 'unknown';
ALTER TABLE public.snmp_credentials ADD COLUMN IF NOT EXISTS agent_id uuid REFERENCES public.agents(id), ADD COLUMN IF NOT EXISTS organization_id uuid REFERENCES public.organizations(id);
UPDATE public.snmp_credentials s SET agent_id=m.agent_id, organization_id=m.organization_id FROM public.mikrotik_api_credentials m WHERE s.concentrador_id=m.concentrador_id AND s.agent_id IS NULL;
UPDATE public.concentradores SET api_last_success_at=ultima_coleta WHERE api_last_success_at IS NULL;
ALTER TABLE public.device_interfaces ADD COLUMN IF NOT EXISTS counter_source text, ADD COLUMN IF NOT EXISTS last_device_uptime bigint;
ALTER TABLE public.metric_samples ADD COLUMN IF NOT EXISTS source text NOT NULL DEFAULT 'legacy';
CREATE TABLE public.api_collection_slots (agent_id uuid NOT NULL REFERENCES public.agents(id), slot_at timestamptz NOT NULL, PRIMARY KEY(agent_id,slot_at));
GRANT ALL ON public.api_collection_slots TO service_role;
ALTER TABLE public.api_collection_slots ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_api_collection_slot(_agent uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE local_now timestamp := now() AT TIME ZONE 'America/Bahia'; n int; BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'forbidden'; END IF; IF extract(hour FROM local_now)::int NOT IN (0,6,12,18) OR extract(minute FROM local_now)::int<>0 THEN RETURN false; END IF; INSERT INTO public.api_collection_slots(agent_id,slot_at) VALUES (_agent,date_trunc('hour',now())) ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n=1; END $$;
REVOKE ALL ON FUNCTION public.claim_api_collection_slot(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_api_collection_slot(uuid) TO service_role;
-- Validate assignments even for direct API writes; tenant/agent/target must agree.
CREATE OR REPLACE FUNCTION public.guard_snmp_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ao uuid; target_org uuid; BEGIN IF NEW.agent_id IS NULL THEN RETURN NEW; END IF; SELECT organization_id INTO ao FROM agents WHERE id=NEW.agent_id; IF NEW.concentrador_id IS NOT NULL THEN SELECT organization_id INTO target_org FROM concentradores WHERE id=NEW.concentrador_id; ELSE SELECT organization_id INTO target_org FROM rbs WHERE id=NEW.rbs_id; END IF; IF ao IS DISTINCT FROM target_org OR NEW.organization_id IS DISTINCT FROM ao THEN RAISE EXCEPTION 'Agente e equipamento devem pertencer à mesma empresa'; END IF; IF auth.role()<>'service_role' AND (NOT public.has_role(auth.uid(),'admin') OR (ao IS NOT NULL AND NOT public.is_org_member(auth.uid(),ao))) THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN NEW; END $$;
CREATE TRIGGER snmp_assignment_guard BEFORE INSERT OR UPDATE ON public.snmp_credentials FOR EACH ROW EXECUTE FUNCTION public.guard_snmp_assignment();
REVOKE SELECT ON public.snmp_credentials FROM authenticated,anon;
GRANT SELECT(id,concentrador_id,rbs_id,agent_id,organization_id,enabled,version,port,username,auth_proto,priv_proto,poll_interval_seconds,timeout_ms,retries,last_poll_at,last_error,created_at,updated_at) ON public.snmp_credentials TO authenticated;
CREATE OR REPLACE FUNCTION public.save_snmp_credentials(_id uuid,_values jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid:=(_values->>'agent_id')::uuid; org uuid; cid uuid:=nullif(_values->>'concentrador_id','')::uuid; rid uuid:=nullif(_values->>'rbs_id','')::uuid; old_org uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT organization_id INTO org FROM agents WHERE id=aid AND enabled; IF NOT FOUND OR (org IS NOT NULL AND NOT public.is_org_member(auth.uid(),org)) THEN RAISE EXCEPTION 'Agente não autorizado'; END IF; IF (cid IS NULL)=(rid IS NULL) THEN RAISE EXCEPTION 'Selecione um equipamento'; END IF; IF _id IS NOT NULL THEN SELECT organization_id INTO old_org FROM snmp_credentials WHERE id=_id; IF NOT FOUND OR (old_org IS NOT NULL AND NOT public.is_org_member(auth.uid(),old_org)) THEN RAISE EXCEPTION 'forbidden'; END IF; END IF;
INSERT INTO snmp_credentials(id,concentrador_id,rbs_id,agent_id,organization_id,enabled,version,port,community,username,auth_proto,auth_password,priv_proto,priv_password,poll_interval_seconds,timeout_ms,retries) VALUES(coalesce(_id,gen_random_uuid()),cid,rid,aid,org,coalesce((_values->>'enabled')::boolean,true),(_values->>'version')::snmp_version,(_values->>'port')::int,nullif(_values->>'community',''),nullif(_values->>'username',''),(_values->>'auth_proto')::snmp_auth_proto,nullif(_values->>'auth_password',''),(_values->>'priv_proto')::snmp_priv_proto,nullif(_values->>'priv_password',''),30,(_values->>'timeout_ms')::int,(_values->>'retries')::int)
ON CONFLICT(id) DO UPDATE SET concentrador_id=EXCLUDED.concentrador_id,rbs_id=EXCLUDED.rbs_id,agent_id=EXCLUDED.agent_id,organization_id=EXCLUDED.organization_id,enabled=EXCLUDED.enabled,version=EXCLUDED.version,port=EXCLUDED.port,community=coalesce(EXCLUDED.community,snmp_credentials.community),username=EXCLUDED.username,auth_proto=EXCLUDED.auth_proto,auth_password=coalesce(EXCLUDED.auth_password,snmp_credentials.auth_password),priv_proto=EXCLUDED.priv_proto,priv_password=coalesce(EXCLUDED.priv_password,snmp_credentials.priv_password),poll_interval_seconds=30,timeout_ms=EXCLUDED.timeout_ms,retries=EXCLUDED.retries; END $$;
REVOKE ALL ON FUNCTION public.save_snmp_credentials(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_snmp_credentials(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.pppoe_summary() RETURNS jsonb LANGUAGE sql STABLE SET search_path=public AS $$ SELECT jsonb_build_object('clients',(SELECT count(DISTINCT(concentrador_id,username)) FROM pppoe_sessions),'session_records',(SELECT count(*) FROM pppoe_sessions),'online_fresh',NULL,'online_stale',(SELECT count(*) FROM pppoe_sessions WHERE online),'snapshot_online',(SELECT sum(usuarios_online) FROM concentradores WHERE api_last_success_at IS NOT NULL),'last_sync',(SELECT max(api_last_success_at) FROM concentradores),'realtime_available',false) $$;
CREATE OR REPLACE FUNCTION public.dashboard_summary() RETURNS jsonb LANGUAGE sql STABLE SET search_path=public AS $$ SELECT jsonb_build_object('online_now',NULL,'online_stale',(SELECT count(*) FROM pppoe_sessions WHERE online),'snapshot_online',(SELECT sum(usuarios_online) FROM concentradores WHERE api_last_success_at IS NOT NULL),'last_session_update',(SELECT max(api_last_success_at) FROM concentradores),'disconnected_24h_clients',(SELECT count(DISTINCT(concentrador_id,username)) FROM eventos WHERE tipo='disconnect' AND created_at>=now()-interval '24 hours'),'individual_drops_24h',(SELECT count(*) FROM eventos WHERE tipo='disconnect' AND created_at>=now()-interval '24 hours'),'mass_incidents_24h',(SELECT count(*) FROM eventos WHERE tipo='device_down' AND metadata->>'scope'='mass' AND created_at>=now()-interval '24 hours'),'mass_affected_24h',(SELECT coalesce(sum((metadata->>'count')::int),0) FROM eventos WHERE tipo='device_down' AND metadata->>'scope'='mass' AND created_at>=now()-interval '24 hours'),'last_collect_at',(SELECT max(snmp_last_success_at) FROM concentradores),'last_agent_seen_at',(SELECT max(last_seen_at) FROM agents WHERE enabled),'realtime_available',false) $$;
COMMENT ON COLUMN public.concentradores.ultima_coleta IS 'Last valid primary SNMP collection for new collector; legacy API timestamps must not be used as monitoring health. API timestamp is api_last_success_at.';